/// <summary>
/// Service class
/// </summary>
class METUpdateSlotAreaService extends METSysOperationService
{
    private guid                   topPickingProcessId;
}

Method.Source:
/// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METUpdateSlotAreaTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METUpdateSlotAreaTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:UpdateSlotAreaJob";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METUpdateSlotAreaContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Initialise global variables.
/// </summary>
public void initialise()
{
    super();

    this.stageDataIntoQueue();
}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METUpdateSlotAreaContract contract = _taskDataContract as METUpdateSlotAreaContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Data contract object
/// </summary>
/// <returns></returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METUpdateSlotAreaContract();
}

/// <summary>
/// Stages data int table <c>METABNValidationJobQueue</c>.
/// </summary>
void stageDataIntoQueue()
{
    #OCCRetryCount

    METUpdateSlotAreaContract contract;

    topPickingProcessId     = newGuid();

    contract                = dataContract as METUpdateSlotAreaContract;

    try
    {
        ttsbegin;

        METUpdateSlotAreaJobQueue::cleanUpUpdateSlotAreaJobQueue();

        if(contract.parmInventLocationId())
        {
            this.stageDataIntoQueueQueryFiltered(contract.parmInventLocationId());
        }

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        curext(); // avoids a warning about an empty block
    }
}

/// <summary>
/// Insert data into Queue table
/// </summary>
/// <param name = "_inventLocationId">InventLocationId</param>
void stageDataIntoQueueQueryFiltered(InventLocationId _inventLocationId)
{
    METUpdateSlotAreaJobQueue metUpdateSlotAreaJobQueue;
    ReqItemTable reqItemTable;
    METReqItemTable metReqItemTable;
    InventDim inventDim; 

    insert_recordset metUpdateSlotAreaJobQueue(ProcessId,RefTableId, RefRecId)
        select topPickingProcessId, TableId, RecId from reqItemTable
            exists join inventDim
        where inventDim.inventDimId == reqItemTable.CovInventDimId
            && inventDim.InventLocationId == _inventLocationId
            exists join metReqItemTable
        where metReqItemTable.RefRecId == reqItemTable.RecId && metReqItemTable.SlotLoc1Area != '';
}
